Item.method_code:
const { commandFactory } = options;
const itemNode = window.getItem();
const claimCommand = commandFactory('ClaimItem', { itemNode });
const unclaimCommand = commandFactory('UnclaimItem', { itemNode });
const canClaimExecute = claimCommand.canExecute();
const canUnclaimExecute = unclaimCommand.canExecute();
const disabled = !canClaimExecute && !canUnclaimExecute;
const itemAction = itemNode.getAttribute('action');
const hidden = itemAction === 'add';

let image = 'ClaimOff.svg';
let title = 'common.lock';
const claimedById = aras.getItemProperty(itemNode, 'locked_by_id');
const isClaimedByMe = claimedById === aras.user.id;
let claimedByKeyedName = '';
const isClaimedByOther = claimedById && !isClaimedByMe;
if (isClaimedByOther) {
	image = 'ClaimOther.svg';
	title = 'claim_button.claimed_by_another_user';
	claimedByKeyedName = aras.getItemPropertyAttribute(itemNode, 'locked_by_id', 'keyed_name');
} else if (canUnclaimExecute) {
	image = 'ClaimOn.svg';
	title = 'common.unlock';
}

return {
	hidden,
	image: '../images/' + image,
	claimed: canUnclaimExecute,
	disabled,
	tooltip_template: aras.getResource('', title, claimedByKeyedName)
};
